using System;
using System.Collections;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
namespace Wildfolk.Tests
{
    public sealed class ContentExpansionHostTests
    {
        private NetworkSession session;private NetworkCreatureWorld net;private NetworkPlayer player;
        private IEnumerator Host()
        {var task=session.Host(ConnectionRoute.LocalNetwork);for(var i=0;i<600 && !task.IsCompleted;i++)yield return null;Assert.That(task.IsCompleted && task.Result,Is.True,session.LastFailure);Assert.That(session.EnterGame(),Is.True);var deadline=Time.realtimeSinceStartup+10;do{yield return new WaitForSecondsRealtime(.05f);player=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.NetworkObject.IsPlayerObject);}while(player==null && Time.realtimeSinceStartup<deadline);Assert.That(player,Is.Not.Null,"scene="+UnityEngine.SceneManagement.SceneManager.GetActiveScene().name+" state="+session.State+" host="+session.Manager.IsHost+" connected="+session.Manager.ConnectedClients.Count+" ready="+(NetworkCreatureWorld.Active==null ? "none" : NetworkCreatureWorld.Active.Ready.ToString())+" restored="+(session.PreparedWorld!=null));net=NetworkCreatureWorld.Active;net.Clock.enabled=net.Goblins.enabled=net.Night.enabled=false;player.Motor.enabled=false;player.GetComponent<PlayerInputAdapter>().enabled=false;net.World.Chunks.Reconcile();net.World.Chunks.DrainPending();net.FlushPending();yield return null;}
        private void Move(Vector2 p){player.Commands.Session.CloseInventory();player.transform.position=p;player.GetComponent<Rigidbody2D>().position=p;Physics2D.SyncTransforms();net.World.Chunks.Reconcile();net.World.Chunks.DrainPending();net.FlushPending();}
        [UnityTest]public IEnumerator FishingContainerUtilityAndNewBuildingsPersistThroughHostAuthority()
        {
            SceneFlow.Home(SaveRepository.Default());yield return null;yield return null;UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();session=NetworkSession.Instance;session.WorldRepository=new SaveRepository(Path.Combine(Application.temporaryCachePath,"Codex_QA_ContentExpansion_"+Guid.NewGuid().ToString("N"),"world.json"));session.ProfileOverride=Guid.NewGuid().ToString("N");session.NewWorldGenerationVersion=2;yield return Host();
            var bag=player.GetComponent<PlayerInventory>();var inventory=player.GetComponent<NetworkInventory>();var rod=net.Catalog.Item("fishing_rod");bag.Model.Add(rod,1);bag.SelectSlot(0);Move(new Vector2(net.World.Map.Continental.RiverAt(1000)+7,1000));player.Motor.Avatar.Facing.Face(Vector2.left);Assert.That(player.Attack(),Is.True);yield return new WaitForSeconds(3.1f);Assert.That(player.Attack(),Is.True);Assert.That(player.Attack(),Is.False);Assert.That(bag.Model.CountItem(net.Catalog.Item("raw_fish")),Is.EqualTo(1));
            var arrows=net.Catalog.Item("arrow");var bow=net.Catalog.Item("bow");bag.Model.Add(arrows,12);bag.Model.Add(bow,1);var bowSlot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==bow);bag.SelectSlot(bowSlot);Assert.That(player.Attack(),Is.True);yield return new WaitForSeconds(.42f);Assert.That(bag.Model.CountItem(arrows),Is.EqualTo(11));Assert.That(UnityEngine.Object.FindObjectsByType<NetworkProjectile>(FindObjectsSortMode.None).Any(x=>x.IsSpawned && x.IsServer && x.Visual.Value==Array.IndexOf(net.Catalog.Items,arrows)),Is.True);yield return new WaitForSeconds(.4f);
            var skin=net.Catalog.Item("waterskin");bag.Model.Add(skin,1,2,LiquidState.Clean);var slot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==skin);bag.SelectSlot(slot);player.GetComponent<PlayerSurvival>().Model.SetMeters(40,0);Assert.That(player.Attack(),Is.True);Assert.That(bag.SelectedStack.Charges,Is.EqualTo(1));Assert.That(inventory.Slots[slot].Charges,Is.EqualTo(1));
            var lantern=net.Catalog.Item("lantern");bag.Model.Add(lantern,1);var lightSlot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==lantern);player.Commands.Session.OpenInventory();Assert.That(inventory.Execute(InventoryOperation.Equip,lightSlot,0,0,0,inventory.Revision.Value),Is.True);player.Commands.Session.CloseInventory();Assert.That(player.Status.Value.Utility,Is.EqualTo(Array.IndexOf(net.Catalog.Items,lantern)));
            Move(new Vector2(0,-6));var item=net.Catalog.Item("reinforced_gate");bag.Model.Add(item,2);slot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==item);bag.SelectSlot(slot);var placement=player.GetComponent<PlayerPlacement>();player.Motor.Avatar.Facing.Face(Vector2.down);var point=(Vector2)player.transform.position+Vector2.down*placement.Settings.PlacementDistance;foreach(var r in UnityEngine.Object.FindObjectsByType<ResourceNode>(FindObjectsSortMode.None))if(Vector2.Distance(r.transform.position,point)<5)r.gameObject.SetActive(false);Physics2D.SyncTransforms();var revision=inventory.Revision.Value;var construction=player.GetComponent<NetworkConstruction>();Assert.That(construction.ExecutePlace(revision,slot,point),Is.True);Assert.That(construction.ExecutePlace(revision,slot,point),Is.False);var placed=WorldPlaceable.Active.Single(f=>f.Definition.Item==item);var id=placed.SaveId;Assert.That(session.TrySaveWorld(),Is.True);
            session.Leave();for(var i=0;i<300 && session.State!=NetworkSessionState.Idle;i++)yield return null;yield return new WaitForSeconds(1);yield return Host();bag=player.GetComponent<PlayerInventory>();Assert.That(bag.Model.Capture().Single(x=>x.Item=="waterskin").Charges,Is.EqualTo(1));Assert.That(player.Equipment.Utility.Id,Is.EqualTo("lantern"));Move(point+Vector2.right*4);yield return null;Assert.That(WorldPlaceable.Active.Count(f=>f.SaveId==id),Is.EqualTo(1));
        }
        [UnityTearDown]public IEnumerator Close(){if(session!=null && session.State!=NetworkSessionState.Idle){session.Leave(true,true);for(var i=0;i<300 && session.State!=NetworkSessionState.Idle;i++)yield return null;}Time.timeScale=1;}
    }
}
